/**
 * Local diagnostic record for one hosted execution. Flushed with durable
 * execution history and process output.
 */
import { createHash, randomBytes } from "node:crypto";
import { mkdir, rename, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { HOSTED_EXECUTION_DIAG_FILENAME, parseHostedFailureClassification, } from "./hosted-delivery-protocol.js";
import { isRecord } from "./is-record.js";
export const HOSTED_EXECUTION_DIAG_VERSION = 1;
/** Cap so a runaway message cannot fill the guest disk or the host log. */
export const HOSTED_EXECUTION_DIAG_MAX_BYTES = 4096;
/**
 * Correlate the fixed-path record with the execution that produced it. An
 * interrupted attempt can otherwise leave the previous execution's terminal
 * record behind.
 *
 * Derive the id from the admission token. The one-way digest prevents the
 * token itself from reaching disk or logs.
 */
export function hostedExecutionDiagId(admissionToken) {
    return createHash("sha256").update(admissionToken).digest("hex").slice(0, 16);
}
/** Written before the turn starts so a stalled execution still has a record. */
export const HOSTED_EXECUTION_DIAG_RUNNING_STATUS = "running";
const DIAG_KEYS = new Set([
    "v",
    "executionId",
    "writtenAt",
    "sessionPublicId",
    "sessionId",
    "turnStatus",
    "durationMs",
    "message",
    "stack",
    "signalAborted",
    "requestId",
    "abortReason",
    "failureCode",
    "errorCode",
    "classification",
]);
function isHostedAbortReason(value) {
    return (value === "signal_abort" ||
        value === "runner_cancelled" ||
        value === "runner_error" ||
        value === "execute_throw");
}
function boundedOptionalString(value, max) {
    return typeof value === "string" && value.length > 0
        ? value.length > max
            ? `${value.slice(0, max)}…`
            : value
        : undefined;
}
/** Bounds for a short error stack summary. */
export const HOSTED_ERROR_STACK_LINE_COUNT = 5;
export const HOSTED_ERROR_SNIPPET_MAX_CHARS = 700;
/**
 * Bounded throw text for diagnostics and non-hosted 500 bodies. Prefers
 * `Error.stack` with its message and first frames.
 */
export function hostedErrorStackSnippet(error) {
    if (error instanceof Error) {
        const stack = error.stack?.trim();
        if (stack !== undefined && stack.length > 0) {
            const lines = stack
                .split("\n")
                .map((line) => line.trimEnd())
                .filter((line) => line.trim().length > 0)
                .slice(0, HOSTED_ERROR_STACK_LINE_COUNT);
            const text = lines.join("\n");
            return text.length > HOSTED_ERROR_SNIPPET_MAX_CHARS
                ? `${text.slice(0, HOSTED_ERROR_SNIPPET_MAX_CHARS)}…`
                : text;
        }
        return error.message.length > HOSTED_ERROR_SNIPPET_MAX_CHARS
            ? `${error.message.slice(0, HOSTED_ERROR_SNIPPET_MAX_CHARS)}…`
            : error.message;
    }
    const text = String(error);
    if (text.length === 0) {
        return "";
    }
    return text.length > HOSTED_ERROR_SNIPPET_MAX_CHARS
        ? `${text.slice(0, HOSTED_ERROR_SNIPPET_MAX_CHARS)}…`
        : text;
}
/** Hosted response text without stack frames. */
export function hostedErrorMessageOnly(error) {
    const text = error instanceof Error && error.message.trim().length > 0
        ? error.message.trim()
        : String(error).trim();
    if (text.length === 0) {
        return "Internal server error.";
    }
    const firstFrame = text.search(/\n\s+at\s/);
    const message = firstFrame === -1 ? text : text.slice(0, firstFrame).trimEnd();
    if (message.length === 0) {
        return "Internal server error.";
    }
    return message.length > HOSTED_ERROR_SNIPPET_MAX_CHARS
        ? `${message.slice(0, HOSTED_ERROR_SNIPPET_MAX_CHARS)}…`
        : message;
}
export function hostedExecutionDiagPath(stateRoot) {
    return join(stateRoot, HOSTED_EXECUTION_DIAG_FILENAME);
}
export function abortReasonFromTurnStatus(status, cancellationReason) {
    if (status === "finished") {
        return undefined;
    }
    if (status === "cancelled") {
        return cancellationReason === "signal" ? "signal_abort" : "runner_cancelled";
    }
    return "runner_error";
}
export function parseHostedExecutionDiag(raw) {
    if (raw.length === 0 || raw.length > HOSTED_EXECUTION_DIAG_MAX_BYTES) {
        return undefined;
    }
    let parsed;
    try {
        parsed = JSON.parse(raw);
    }
    catch {
        return undefined;
    }
    if (!isRecord(parsed)) {
        return undefined;
    }
    const body = parsed;
    if (Object.keys(body).some((key) => !DIAG_KEYS.has(key))) {
        return undefined;
    }
    if (body.v !== HOSTED_EXECUTION_DIAG_VERSION ||
        typeof body.executionId !== "string" ||
        body.executionId.length === 0 ||
        body.executionId.length > 64 ||
        typeof body.writtenAt !== "string" ||
        body.writtenAt.length === 0 ||
        body.writtenAt.length > 64 ||
        typeof body.sessionPublicId !== "string" ||
        body.sessionPublicId.length === 0 ||
        body.sessionPublicId.length > 128 ||
        typeof body.sessionId !== "string" ||
        body.sessionId.length > 128 ||
        typeof body.turnStatus !== "string" ||
        body.turnStatus.length === 0 ||
        body.turnStatus.length > 64 ||
        typeof body.durationMs !== "number" ||
        !Number.isFinite(body.durationMs) ||
        body.durationMs < 0) {
        return undefined;
    }
    const message = boundedOptionalString(body.message, 1024);
    const stack = boundedOptionalString(body.stack, HOSTED_ERROR_SNIPPET_MAX_CHARS);
    const requestId = boundedOptionalString(body.requestId, 128);
    const failureCode = boundedOptionalString(body.failureCode, 64);
    const errorCode = boundedOptionalString(body.errorCode, 64);
    const classification = body.classification === undefined
        ? undefined
        : parseHostedFailureClassification(body.classification);
    if (body.classification !== undefined && classification === undefined) {
        return undefined;
    }
    const abortReason = typeof body.abortReason === "string" && isHostedAbortReason(body.abortReason)
        ? body.abortReason
        : undefined;
    if (body.abortReason !== undefined && abortReason === undefined) {
        return undefined;
    }
    if (body.signalAborted !== undefined && typeof body.signalAborted !== "boolean") {
        return undefined;
    }
    return {
        v: HOSTED_EXECUTION_DIAG_VERSION,
        executionId: body.executionId,
        writtenAt: body.writtenAt,
        sessionPublicId: body.sessionPublicId,
        sessionId: body.sessionId,
        turnStatus: body.turnStatus,
        durationMs: body.durationMs,
        ...(message === undefined ? {} : { message }),
        ...(stack === undefined ? {} : { stack }),
        ...(body.signalAborted === true ? { signalAborted: true } : {}),
        ...(requestId === undefined ? {} : { requestId }),
        ...(abortReason === undefined ? {} : { abortReason }),
        ...(failureCode === undefined ? {} : { failureCode }),
        ...(errorCode === undefined ? {} : { errorCode }),
        ...(classification === undefined ? {} : { classification }),
    };
}
/**
 * Overwrite the per-execution diag file. Soft-fail: a write error must not
 * change the hosted-execution HTTP reply.
 */
export async function writeHostedExecutionDiag(stateRoot, diag) {
    const path = hostedExecutionDiagPath(stateRoot);
    const tmp = `${path}.${randomBytes(8).toString("hex")}.tmp`;
    try {
        await mkdir(stateRoot, { recursive: true });
        const serialized = JSON.stringify(diag);
        const body = serialized.length > HOSTED_EXECUTION_DIAG_MAX_BYTES
            ? JSON.stringify({
                ...diag,
                stack: undefined,
                message: boundedOptionalString(diag.message, 256),
            })
            : serialized;
        await writeFile(tmp, body, "utf8");
        await rename(tmp, path);
    }
    catch {
        await unlink(tmp).catch(() => undefined);
    }
}
